(window.HistoryAtlas.PERSONS = window.HistoryAtlas.PERSONS || {})["matteo-ricci"] = {"id":"matteo-ricci","name":"利玛窦","name_alt":"Matteo Ricci（字西泰）","group":"世界","born":1552,"died":1610,"born_approx":false,"died_approx":false,"role":"意大利耶稣会传教士、学者","polity":"","summary":"利玛窦生于意大利马切拉塔，在罗马加入耶稣会并师从数学家克拉维乌斯。1582年抵达澳门，次年入居肇庆，此后经韶州、南昌、南京北上，1601年获准居留北京。他采取适应儒家文化的传教策略，绘制《坤舆万国全图》，与徐光启合译《几何原本》前六卷，1610年卒于北京，获赐葬地。","confidence":"史料确证","sources":"利玛窦《耶稣会与天主教进入中国史》（金尼阁整理本即《利玛窦中国札记》）、利玛窦书信、《明史·意大里亚传》；Ronnie Po-chia Hsia《紫禁城里的耶稣会士》","stops":[{"year":1552,"to":1552,"x":757.7,"y":183.8,"place":"马切拉塔（今意大利马尔凯大区）","event":"10月6日生于教皇国马切拉塔一个药剂师家庭。","kind":"出生","confidence":"史料确证","source":"Hsia"},{"year":1568,"to":1576,"x":753.8,"y":190.8,"place":"罗马（今意大利）","event":"赴罗马学习法律，1571年加入耶稣会，在罗马学院师从克拉维乌斯学习数学与天文。","kind":"求学","confidence":"史料确证","source":"耶稣会档案；Hsia"},{"year":1577,"to":1577,"x":670.1,"y":199.3,"place":"科英布拉（今葡萄牙）","event":"获准赴东方传教，在科英布拉学习葡萄牙语等候启程。","kind":"求学","confidence":"学界推测","source":"Hsia"},{"year":1578,"to":1581,"x":1017.7,"y":324.2,"place":"果阿（今印度果阿邦）","event":"3月自里斯本启航，9月抵达果阿，在果阿与科钦教学并完成神学学业，1580年在科钦晋铎。","kind":"求学","confidence":"史料确证","source":"利玛窦书信"},{"year":1582,"to":1582,"x":1183,"y":290.3,"place":"澳门","event":"8月奉范礼安之召抵达澳门，学习汉语。","kind":"传教","confidence":"史料确证","source":"利玛窦《耶稣会与天主教进入中国史》"},{"year":1583,"to":1588,"x":1178,"y":286.3,"place":"肇庆（今广东肇庆）","event":"9月与罗明坚获两广总督府准许入居肇庆，建\"仙花寺\"，刊刻最早的中文世界地图。","kind":"传教","confidence":"史料确证","source":"利玛窦《耶稣会与天主教进入中国史》"},{"year":1589,"to":1594,"x":1180.8,"y":277.2,"place":"韶州（今广东韶关）","event":"被逐出肇庆后移居韶州，结识瞿汝夔，开始改穿儒服。","kind":"传教","confidence":"史料确证","source":"利玛窦《耶稣会与天主教进入中国史》"},{"year":1595,"to":1597,"x":1185.9,"y":257.4,"place":"南昌（今江西南昌）","event":"北上南京未果，转居南昌，著《交友论》，与建安王等宗室士人交往。","kind":"著述","confidence":"史料确证","source":"利玛窦《耶稣会与天主教进入中国史》"},{"year":1598,"to":1598,"x":1170.6,"y":200.8,"place":"北京","event":"随礼部尚书王忠铭首次进京，因朝鲜战事未能留居，旋即南返。","kind":"旅行","confidence":"史料确证","source":"利玛窦《耶稣会与天主教进入中国史》"},{"year":1599,"to":1599,"x":1193.3,"y":240.2,"place":"南京（今江苏南京）","event":"定居南京，与李贽、徐光启等士人往来。","kind":"传教","confidence":"史料确证","source":"利玛窦《耶稣会与天主教进入中国史》"},{"year":1600,"to":1600,"x":1175.2,"y":204.9,"place":"天津","event":"携贡品再度北上，在天津一带被税监马堂扣留数月。","kind":"旅行","confidence":"史料确证","source":"利玛窦《耶稣会与天主教进入中国史》"},{"year":1601,"to":1606,"x":1170.6,"y":200.8,"place":"北京","event":"1月抵京向万历帝进献自鸣钟等物，获准居留；1602年刊刻《坤舆万国全图》，1603年刊行《天主实义》。","kind":"传教","confidence":"史料确证","source":"利玛窦《耶稣会与天主教进入中国史》、《明史·意大里亚传》"},{"year":1607,"to":1607,"x":1170.6,"y":200.8,"place":"北京","event":"与徐光启合译《几何原本》前六卷刊行。","kind":"著述","confidence":"史料确证","source":"《几何原本》徐光启序"},{"year":1610,"to":1610,"x":1170.6,"y":200.8,"place":"北京","event":"5月11日病逝于北京，万历帝赐阜成门外滕公栅栏为葬地。","kind":"去世","confidence":"史料确证","source":"《明史·意大里亚传》、熊三拔与庞迪我报告"}]};
